{{ config(materialized='table') }}

with
quarantined as (
    select
        nav_id,
        meridex_fund_id,
        nav_date,
        nav_usd,
        called_capital_usd,
        distributed_capital_usd,
        violation_00,
        violation_01,
        violation_02,
        violation_03
    from {{ ref("investment__meridex_fund_nav_extract__checked") }}
),
violations as (
    select
        'nav_id_not_null' as rule_name,
        nav_id,
        meridex_fund_id,
        nav_date,
        nav_usd,
        called_capital_usd,
        distributed_capital_usd
    from quarantined
    where violation_00

    union all

    select
        'nav_id_unique' as rule_name,
        nav_id,
        meridex_fund_id,
        nav_date,
        nav_usd,
        called_capital_usd,
        distributed_capital_usd
    from quarantined
    where violation_01

    union all

    select
        'meridex_fund_id_not_null' as rule_name,
        nav_id,
        meridex_fund_id,
        nav_date,
        nav_usd,
        called_capital_usd,
        distributed_capital_usd
    from quarantined
    where violation_02

    union all

    select
        'nav_date_not_null' as rule_name,
        nav_id,
        meridex_fund_id,
        nav_date,
        nav_usd,
        called_capital_usd,
        distributed_capital_usd
    from quarantined
    where violation_03
)

select
    rule_name,
    nav_id,
    meridex_fund_id,
    nav_date,
    nav_usd,
    called_capital_usd,
    distributed_capital_usd
from violations
